Source code in <code>meedee/_monitor.py</code> <pre><code>def watch(connection: midi.Input, config: Monitor) -&gt; int:
    session = Session(config, connection.stream, connection.clock)
    start = monotonic()
    interrupted = False
    failure: str | None = None
    delivery = None
    if config.metrics:
        from . import metrics

        delivery = metrics.Delivery(start_ns=monotonic_ns())
    try:
        with connection:
            try:
                while config.duration is None or monotonic() - start &lt; config.duration:
                    for r in session.counter(connection.dropped_packets):
                        emit(r, config.output)
                    if (error := connection.failure) is not None:
                        raise error
                    remaining = (
                        0.05
                        if config.duration is None
                        else min(
                            0.05, max(0.0, config.duration - (monotonic() - start))
                        )
                    )
                    item = connection.receive(timeout=remaining)
                    if item is not None:
                        if delivery is not None and isinstance(item, messages.Message):
                            delivery.observe(monotonic_ns())
                        for r in session.feed(item):
                            emit(r, config.output)
            except KeyboardInterrupt:
                interrupted = True
    except (
        midi.MidiError,
        midi.StateError,
        midi.CallbackThreadError,
        midi.NativePanicError,
        midi.ResourceError,
        midi.WorkerError,
        midi.WorkerTimeoutError,
        ExceptionGroup,
    ) as error:
        failure = str(error)[: config.preview_bytes * 2]
        emit({"kind": "failure", "reason": failure}, config.output)
    for r in session.counter(connection.dropped_packets):
        emit(r, config.output)
    report = session.observer.snapshot()
    data = inspection_data(report)
    data.pop("complete")
    data.pop("problem")
    data.update(
        {
            "kind": "summary",
            "live": True,
            "interrupted": interrupted,
            "failure": failure,
            "filtered": session.filtered,
            "transport_drop_total": session.transport_drops,
            "history": list(session.history),
        }
    )
    if delivery is not None:
        measurement = delivery.snapshot(monotonic_ns())
        intervals = measurement.intervals
        data["metrics"] = {
            "clock": "host_monotonic",
            "events": measurement.events,
            "elapsed_ns": measurement.elapsed_ns,
            "events_per_second": (
                measurement.events * 1_000_000_000 / measurement.elapsed_ns
                if measurement.elapsed_ns
                else None
            ),
            "delivery_intervals": {
                n: getattr(intervals, n)
                for n in (
                    "count",
                    "sum_ns",
                    "minimum_ns",
                    "maximum_ns",
                    "upper_bounds_ns",
                    "buckets",
                )
            },
        }
    emit(data, config.output)
    return (
        2
        if failure is not None
        else int(
            bool(
                session.transport_drops
                or session.diagnostics
