    global SHUTTING_DOWN
    with REGISTRY_LOCK:
        SHUTTING_DOWN = True
        contexts = list(CONTEXTS)
        deliveries = list(DELIVERIES)
    for d in deliveries:
        d.retire()
    deadline = monotonic() + max(
        (c.timeout for c in contexts if not c.stopped.is_set()), default=0
